INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6902620, 1040629, 83313, '<td valign="top">If you went to all the same effort as Cristophe did for this scene, you deserve some kudos.</td>', 'If you went to all the same effort as Cristophe did for this scene, you deserve some kudos.', '2012-11-09 00:12:17.000000', NULL, 1),
(6902621, 1040681, 83313, '<td valign="top">What, you couldn''t dress up as a cavewoman and remake my own ribbon from that same challenge? I''m hurt. Well, this outfit is a lot sexier than a bearskin would likely be...</td>', 'What, you couldn''t dress up as a cavewoman and remake my own ribbon from that same challenge? I''m hurt. Well, this outfit is a lot sexier than a bearskin would likely be...', '2012-11-09 00:14:40.000000', NULL, 1),
(6902623, 1040671, 83313, '<td valign="top">Ironically, this is a better shot than the original, but is sure to do much worse on the score. Kudos for doing this one, however.</td>', 'Ironically, this is a better shot than the original, but is sure to do much worse on the score. Kudos for doing this one, however.', '2012-11-09 00:16:39.000000', NULL, 1),
(6902632, 1040613, 64446, '<td valign="top">Kudos for your bravery in pushing this homage to a different level!  A poisoned attitude, the model is not intimidated by the vulnerability of the whole set up. Great lighting, focus and movement. Excellent!!!</td>', 'Kudos for your bravery in pushing this homage to a different level!  A poisoned attitude, the model is not intimidated by the vulnerability of the whole set up. Great lighting, focus and movement. Excellent!!!', '2012-11-09 00:26:19.000000', NULL, 1),
(6902637, 1040681, 64446, '<td valign="top">For sure, you''ve got a much interesting model. That alone will give at least 3 extra points... :)<br/>A neat image, perfect lighting and her expression is priceless. Excellent job!!!</td>', 'For sure, you''ve got a much interesting model. That alone will give at least 3 extra points... :)A neat image, perfect lighting and her expression is priceless. Excellent job!!!', '2012-11-09 00:38:53.000000', NULL, 1),
(6902641, 1040639, 40391, '<td valign="top">So much better than the original, well done. Love the colours</td>', 'So much better than the original, well done. Love the colours', '2012-11-09 00:47:00.000000', NULL, 1),
(6902643, 1040048, 54645, '<td valign="top">Oh man. Splendid. Why wait. . . <br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=963227" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/50000-54999/54645/120/Copyrighted_Image_Reuse_Prohibited_963227.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/50000-54999/54645/120/Copyrighted_Image_Reuse_Prohibited_963227.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/50000-54999/54645/120/Copyrighted_Image_Reuse_Prohibited_963227.jpg"/></a></td>', 'Oh man. Splendid. Why wait. . .  ', '2012-11-09 00:48:33.000000', NULL, 1),
(6902684, 1040613, 40391, '<td valign="top">If you wore a black dress it would be perfect, ha! Very well done.</td>', 'If you wore a black dress it would be perfect, ha! Very well done.', '2012-11-09 01:32:20.000000', NULL, 1),
(6902728, 1040648, 40391, '<td valign="top">My pick of the challenge. An amazing image!</td>', 'My pick of the challenge. An amazing image!', '2012-11-09 02:03:03.000000', NULL, 1),
