(6902778, 1040613, 28742, '<td valign="top">ROFL! I''m sure she''s *cough* honored *cough*. :)</td>', 'ROFL! I''m sure she''s *cough* honored *cough*. :)', '2012-11-09 02:50:38.000000', NULL, 1),
