(6902904, 1040680, 15711, '<td valign="top">Amazing how this can be so beautiful.  It almost makes me think it is a transparent animal crawling along.  I like this a lot.</td>', 'Amazing how this can be so beautiful.  It almost makes me think it is a transparent animal crawling along.  I like this a lot.', '2012-11-09 08:38:41.000000', NULL, 1),
(6902906, 1040663, 15711, '<td valign="top">You just can''t go wrong with a fish eye. Love it.</td>', 'You just can''t go wrong with a fish eye. Love it.', '2012-11-09 08:38:56.000000', NULL, 1),
(6902907, 1040647, 15711, '<td valign="top">Gorgeous.  I like the layering to create the border. That red couldn''t be a more perfect color (my favorite!)</td>', 'Gorgeous.  I like the layering to create the border. That red couldn''t be a more perfect color (my favorite!)', '2012-11-09 08:39:33.000000', NULL, 1),
(6902908, 1040357, 15711, '<td valign="top">Looks like "the Scream" by Edvard Munch!!</td>', 'Looks like "the Scream" by Edvard Munch!!', '2012-11-09 08:40:41.000000', NULL, 1),
