INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6907089, 1040504, 97225, '<td valign="top">As far as I can find, this does not emulate a particular ribbon winning photo. It does mimic Librodo''s style, but that doesn''t cover the brief.</td>', 'As far as I can find, this does not emulate a particular ribbon winning photo. It does mimic Librodo''s style, but that doesn''t cover the brief.', '2012-11-15 17:47:40.000000', NULL, 1),
(6907093, 1040687, 97225, '<td valign="top">Excellent emulation. Well done.</td>', 'Excellent emulation. Well done.', '2012-11-15 17:50:59.000000', NULL, 1),
(6907096, 1040683, 97225, '<td valign="top">Very well done ''emulation'', and just as good as the original. One of the best.</td>', 'Very well done ''emulation'', and just as good as the original. One of the best.', '2012-11-15 17:53:14.000000', NULL, 1),
